import Axios from 'axios';
import { GLOBAL_DATA } from '../../config';
import { getCode } from '../context';
let { ssl, host } = GLOBAL_DATA.INIT_OPTIONS;
const instance = Axios.create({
    baseURL: `${ssl ? 'https' : 'http'}://${host}/`,
    timeout: 300000,
});
instance.defaults.headers.post['Content-Type'] = 'application/x-www-form-urlencoded;charset=UTF-8';
instance.interceptors.request.use((config) => {
    const { mode, ssl, host } = GLOBAL_DATA.INIT_OPTIONS;
    const protocol = ssl ? 'https' : 'http';
    const port = mode == 'dev' ? `:8787` : '';
    config.baseURL = `${protocol}://${host}${port}/`;
    config.headers = { 'X-Token': getCode() };
    return config;
}, error => Promise.reject(error));
instance.interceptors.response.use((response) => {
    if (response.status == 200) {
        if (response.data.code == -1) {
            console.error(response.data.msg);
            return;
        }
        if (response.data.code == 0) {
            return Promise.resolve(response.data.data);
        }
        else {
            console.error(response.data.msg);
            return Promise.reject(response.data);
        }
    }
    else {
        return Promise.reject(response);
    }
}, error => {
    const { response } = error;
    if (response) {
        console.error(response.data.msg);
        return Promise.reject(error);
    }
    else {
        console.error('网络请求错误');
        return Promise.reject(error);
    }
});
export default instance;
